styl:
.b-iq-hero-17 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-iq-hero-17 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-iq-hero-17 {  background: url("https://fsms.quadcode.com/storage/public/d7/bl/fipcr7pkt9m67kpg/1-2-2-head.png") center top no-repeat;
  background-size: cover;
  background-color: #000;  }
.brad-full.b-iq-hero-17 {  border-radius: 32px !important;  }
.b-iq-hero-17 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 48px;
  line-height: 58px;
  color: #f9f9f9;
  word-break: break-word;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-17 .white-title {  font-size: 26px !important;
    line-height: 32px !important;  }
}
.b-iq-hero-17 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-17 .white-text {  padding-right: 0 !important;  }
}
